int main() {
    int n, k, c;
    if (scanf("%d %d %d", &n, &k, &c) != 3) {
        return 0;
    }

    long long *pref = (long long *)malloc((n + 1) * sizeof(long long));
    pref[0] = 0;
    long long total_sum = 0;
    for (int i = 1; i <= n; i++) {
        long long a;
        scanf("%lld", &a);
        pref[i] = pref[i - 1] + a;
        total_sum += a;
    }

    if (k * c == n) {
        printf("0\n");
        free(pref);
        return 0;
    }

    long long *dp_prev = (long long *)malloc((n + 1) * sizeof(long long));
    long long *dp_curr = (long long *)malloc((n + 1) * sizeof(long long));

    for (int i = 0; i <= n; i++) {
        dp_prev[i] = 0;
    }

    for (int j = 1; j <= k; j++) {
        int start = j * c;
        for (int i = 0; i < start; i++) {
            dp_curr[i] = INF;
        }

        long long min_val = INF;
        for (int i = start; i <= n; i++) {
            long long seg_sum = pref[i] - pref[i - c];
            long long take = dp_prev[i - c] + seg_sum;
            if (take < min_val) {
                min_val = take;
            }
            dp_curr[i] = min_val;
        }

        long long *tmp = dp_prev;
        dp_prev = dp_curr;
        dp_curr = tmp;
    }

    long long min_covered = dp_prev[n];
    long long ans = total_sum - min_covered;

    printf("%lld\n", ans);

    free(pref);
    free(dp_prev);
    free(dp_curr);

    return 0;
}
